head.script:
scwin.count = 0;
scwin.onpageload = function () {
    requires("uiplugin.popup");

};

scwin.onpageunload = function () {

};


scwin.trigger1_onclick = function (e) {
    scwin.count++;
    var options = {
        id: scwin.count,
        type: "pageFramePopup",
        height: "300px",
        width: "400px",
        popupName: "fixPosition: true",
        fixPosition: true
    };
    $p.openPopup("", options);
};

scwin.trigger2_onclick = function (e) {
    scwin.count++;
    var options = {
        id: scwin.count,
        type: "pageFramePopup",
        height: "300px",
        width: "400px",
        popupName: "fixPosition: false",
        fixPosition: false
    };
    $p.openPopup("", options);

};
